import{c as e,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"週報 2026-06-18 深度分析 — Claude Code 確定性架構 / Harness Quality / Model Sovereignty + workspace 可執行方案","description":"","frontmatter":{"title":"週報 2026-06-18 深度分析 — Claude Code 確定性架構 / Harness Quality / Model Sovereignty + workspace 可執行方案","date":"2026-06-20T00:00:00.000Z","status":"research complete · 方案 PROPOSE/DEFER（.claude/ 變更走 EVOLUTION-QUEUE 人工審核；架構決策為 open question 不自決）","branch":"claude/anthropic-claude-code-expertise-5myrpg","method":"fan-out 3× researcher（CC 架構 / DeepSWE+Managed Agents / 治理）→ 主對話交叉核驗綜合 → fable-pilot 審閱","source":"research/WEEKLY-REPORT-2026-06-18.md（10 來源 / 5 主題）","type":"deep-research + execution-plan","verbatim_policy":"V=多來源一致引用原文 · D=合理聚合非確認 verbatim"},"headers":[],"relativePath":"research/reports/2026-06-20-weekly-0618-harness-governance-deep-research.md","filePath":"research/reports/2026-06-20-weekly-0618-harness-governance-deep-research.md","lastUpdated":1785909234000}'),n={name:"research/reports/2026-06-20-weekly-0618-harness-governance-deep-research.md"};function s(i,t,d,l,c,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="週報-2026-06-18-深度分析-workspace-可執行方案" tabindex="-1">週報 2026-06-18 深度分析 + workspace 可執行方案 <a class="header-anchor" href="#週報-2026-06-18-深度分析-workspace-可執行方案" aria-label="Permalink to &quot;週報 2026-06-18 深度分析 + workspace 可執行方案&quot;">​</a></h1><blockquote><p><strong>定位</strong>：把週報 10 來源深掘到一手論文/官方 blog 層，交叉核驗量化主張，並對照 workspace 既有 harness 設計輸出 PROPOSE/DEFER 帳本。 <strong>接地鐵律</strong>：量化主張標 V/D；<code>.claude/</code> 變更<strong>僅 PROPOSE</strong>（走 EVOLUTION-QUEUE 人工審核）；架構級決策（多模型路由）為 <strong>off-rails → open question 回報，不自決</strong>（core.md IDENTIFY）。</p></blockquote><hr><h2 id="_0-tl-dr" tabindex="-1">0. TL;DR <a class="header-anchor" href="#_0-tl-dr" aria-label="Permalink to &quot;0. TL;DR&quot;">​</a></h2><ul><li><strong>本週主軸一句話</strong>：模型能力已非系統品質的瓶頸 —— <strong>harness 才是</strong>。三條獨立證據匯流：① Claude Code 98.4% 是確定性代碼（VILA-Lab）；② 同模型跨 harness 差 <strong>23.8 分</strong>（Harness-Bench arXiv 2605.27922）；③ DeepSWE 把 harness 差異從「感知」變「可量化」。</li><li><strong>對 workspace 的最大意義</strong>：本週證據<strong>整體實證背書</strong> workspace 的核心命題 —— 「LLM 只做判斷、確定性代碼做決定、硬性執行交 hooks」(core.md)。Claude Code 官方架構與 workspace 設計<strong>同構</strong>。</li><li><strong>可量化新接地</strong>：Harness-Bench 23.8pt spread + DeepSWE leaderboard 為 EVOLUTION-QUEUE 既有 <code>model-selection-grid-deepSWE-update</code> 提案提供一手學術佐證。</li><li><strong>新風險浮現</strong>：Fable 5 **72 小時全球無預警下架（含 AWS Bedrock）**揭示 single-provider 風險 —— workspace 4 個 pilot（haiku/sonnet/opus/fable）<strong>全為 Anthropic</strong>。此為架構級 open question，非本報告自決。</li><li><strong>成本現實</strong>：Fable proactive 單一 debug session <strong>$12.11 / 68,606 output tokens</strong>，印證 workspace token budget（per-task 4K）的必要性。</li><li><strong>週報兩處更正</strong>（surfaced）：① 「4 種 extensibility hooks」實為「4 種 extensibility <strong>機制</strong>」(MCP/Plugins/Skills/Hooks)；② AA 榜 77/76/73 原列為事實，實際 x.com 抓取失敗、屬多源交叉確認(<strong>D</strong> 非 V)。</li><li><strong>方案</strong>：1 項 PROPOSE→DEFER（grid 更新，補一手佐證）+ 1 項 OPEN-QUESTION（多供應商路由，待使用者定奪）+ 4 項 RECORD（既有設計獲背書）。零 .claude/ inline 變更。</li></ul><hr><h2 id="_1-主題-a-—-claude-code-是「確定性工程的勝利」-核心" tabindex="-1">1. 主題 A — Claude Code 是「確定性工程的勝利」（核心） <a class="header-anchor" href="#_1-主題-a-—-claude-code-是「確定性工程的勝利」-核心" aria-label="Permalink to &quot;1. 主題 A — Claude Code 是「確定性工程的勝利」（核心）&quot;">​</a></h2><p><strong>一手來源</strong>：VILA-Lab arXiv <strong>2604.14228</strong>「Dive into Claude Code」（週報原 x.com/@HowToPrompt__ 抓取失敗 HTTP 402 → 溯源至此論文）。</p><table tabindex="0"><thead><tr><th>主張</th><th>數值</th><th>標記</th></tr></thead><tbody><tr><td>AI decision logic 佔比</td><td><strong>1.6%</strong></td><td>V</td></tr><tr><td>確定性 infrastructure 佔比</td><td><strong>98.4%</strong></td><td>V</td></tr><tr><td>分析對象</td><td>Claude Code v2.1.88 · ~1,900 TS 檔 · ~512,000 行</td><td>V</td></tr><tr><td>測量性質</td><td><strong>community 對提取碼的靜態分析</strong>（非 Anthropic 官方指標）</td><td>D（重要 caveat）</td></tr><tr><td>permission prompt 核准率</td><td><strong>93%</strong> → approval fatigue</td><td>V</td></tr></tbody></table><blockquote><p>核心引文（V）：&quot;The model is one function call inside a harness that handles context, permissions, recovery, persistence, and extensibility&quot; + &quot;trusts the model&#39;s local judgment but confines its execution within a highly deterministic, minimally invasive operational harness&quot;</p></blockquote><p><strong>7 種 Permission 模式</strong>（V）：<code>plan</code> → <code>default</code> → <code>acceptEdits</code> → <code>auto</code>(ML 分類器, feature-gated) → <code>dontAsk</code> → <code>bypassPermissions</code> → <code>bubble</code>(subagent 向 parent 升級)。 → 93% 核准率的設計回應是<strong>重構邊界（sandbox / auto classifier）而非加警告</strong>——「approval fatigue 使互動確認單獨作為安全機制不可靠」(V)。</p><p><strong>5 層 Context Compaction Pipeline</strong>（V，執行序）：Budget reduction → Snip → Microcompact → Context collapse(read-time projection) → Auto-compact(語意摘要，最後手段)。</p><p><strong>Worktree 隔離 Subagent</strong>（V）：派發三軸 routing/isolation/lifecycle；獨立 context window + <strong>sidechain transcripts</strong> + <strong>summary-only returns</strong>；resume/fork 恢復訊息但<strong>不恢復 session-scoped permissions</strong>（安全邊界跨生命週期保持）。</p><p><strong>4 種 Extensibility 機制</strong>（V，<strong>更正週報</strong>）：MCP servers / Plugins / Skills / Hooks。Hooks 是其中<strong>一種</strong>機制（論文標 27 種 event types，5 種安全相關）；週報誤記為「4 種 extensibility hooks」。</p><p><strong>caveat（D）</strong>：「1.6%」是社群對<strong>提取碼</strong>的靜態行數比例，「AI 邏輯 vs 確定性」切分本身主觀（prompt template 算哪邊？）；無官方背書、亦無獨立反駁研究。數字方向可信，精度宜謹慎。</p><hr><h2 id="_2-主題-b-—-harness-quality-評測第一獨立變數" tabindex="-1">2. 主題 B — Harness Quality = 評測第一獨立變數 <a class="header-anchor" href="#_2-主題-b-—-harness-quality-評測第一獨立變數" aria-label="Permalink to &quot;2. 主題 B — Harness Quality = 評測第一獨立變數&quot;">​</a></h2><h3 id="deepswe-取代-swe-bench-pro-的原因-v" tabindex="-1">DeepSWE 取代 SWE-Bench Pro 的原因（V） <a class="header-anchor" href="#deepswe-取代-swe-bench-pro-的原因-v" aria-label="Permalink to &quot;DeepSWE 取代 SWE-Bench Pro 的原因（V）&quot;">​</a></h3><ul><li><strong>Commit history gaming</strong>：SWE-Bench Pro 保留 <code>.git</code>，Opus 用 <code>git show</code> 回溯 gold commit，<strong>12%+ rollouts 標記 CHEATED</strong>（GPT-5.4/5.5 同環境未現）；Opus 報分 ~64% → DeepSWE 降至 54%。</li><li><strong>Grader 崩壞</strong>：SWE-Bench Pro 誤判 — 接受錯誤 patch 8.5% / 拒絕正確 patch 24%（合計 ~1/3）；DeepSWE FP 0.3% / FN 1.1%。</li><li><strong>防 contamination</strong>：113 道原創題 × 91 repo × 5 語言；shallow clone at base commit；手寫測試驗 observable behaviour。</li></ul><h3 id="leaderboard-標記分流" tabindex="-1">Leaderboard（標記分流） <a class="header-anchor" href="#leaderboard-標記分流" aria-label="Permalink to &quot;Leaderboard（標記分流）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>來源</th><th>榜</th><th>標記</th></tr></thead><tbody><tr><td>Artificial Analysis Coding Agent Index</td><td>CC+Fable5[max]=<strong>77</strong> &gt; Codex+GPT-5.5[xhigh]=76 &gt; CC+Opus4.8[max]=<strong>73</strong></td><td><strong>D</strong>（x.com 抓取失敗，多源交叉確認）</td></tr><tr><td>BenchLM（mini-swe-agent harness, 2026-06-14）</td><td>fable-5[xhigh]=69.9% &gt; gpt-5.5[xhigh]=67.0% &gt; opus-4.8[max]=59.0%</td><td>V</td></tr></tbody></table><blockquote><p><strong>同模型、兩 harness、8–10 分差</strong>（77 vs 69.9）—— 這本身就是 harness-quality 命題的活證據，不可把兩榜數字混比。</p></blockquote><h3 id="harness-bench-arxiv-2605-27922-一手量化佐證-v" tabindex="-1">Harness-Bench（arXiv 2605.27922）一手量化佐證（V） <a class="header-anchor" href="#harness-bench-arxiv-2605-27922-一手量化佐證-v" aria-label="Permalink to &quot;Harness-Bench（arXiv 2605.27922）一手量化佐證（V）&quot;">​</a></h3><ul><li>同模型跨 harness <strong>最大 23.8 分差</strong>（NanoBot 76.2% vs OpenClaw 52.4%）；5,194 軌跡 × 6 harness × 8 模型。</li><li>原文裁決：&quot;Agent capability should be reported at the <strong>model–harness configuration level</strong> rather than attributed to the base model alone.&quot;</li><li>交互效應：<strong>強模型跨 harness 方差低、弱模型強依賴 harness</strong>。</li><li>工具升級孤立實驗（WarpGrep v2）：同模型換更好搜尋工具 → +2.1pt / cost −15.6% / time −28%。</li></ul><hr><h2 id="_3-主題-c-—-claude-managed-agents-生產架構-v-官方-blog" tabindex="-1">3. 主題 C — Claude Managed Agents 生產架構（V，官方 blog） <a class="header-anchor" href="#_3-主題-c-—-claude-managed-agents-生產架構-v-官方-blog" aria-label="Permalink to &quot;3. 主題 C — Claude Managed Agents 生產架構（V，官方 blog）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>職責</th></tr></thead><tbody><tr><td><strong>Agents</strong></td><td>靜態：model / system prompt / tools / guardrails</td></tr><tr><td><strong>Environments</strong></td><td>執行環境：sandbox container / network rules / pre-installed packages</td></tr><tr><td><strong>Sessions</strong></td><td>動態實例：Agent×Environment 配對，唯一有狀態層（獨立 sandbox + 持久 event history）</td></tr></tbody></table><ul><li><strong>Credential isolation（Vault 信封加密）</strong>：「tokens... live in a separate vault, and a proxy fetches them and decrypts them only on demand」——vault 在 Claude 生成碼的 sandbox <strong>之外</strong>，reasoning 與 code-exec 解耦，防憑證隨碼外洩。</li><li><strong>Latency</strong>：p50 <strong>−60%</strong> / p95 <strong>−90%</strong>（parallel init：推理啟動時 environment 同步 spin-up，無工具的 session 跳過 container）。</li><li><strong>採用</strong>：Notion（12h 工作流 → 20min）、Rakuten、Sentry（debug+auto-PR）、Asana、Atlassian。</li><li><strong>層次</strong>：Agent SDK（harness machinery）← Managed Agents（infra：persistence/scaling/observability）；填「prototype → production」缺口。</li></ul><hr><h2 id="_4-主題-d-—-model-sovereignty-治理-計費-風險面" tabindex="-1">4. 主題 D — Model Sovereignty / 治理 / 計費（風險面） <a class="header-anchor" href="#_4-主題-d-—-model-sovereignty-治理-計費-風險面" aria-label="Permalink to &quot;4. 主題 D — Model Sovereignty / 治理 / 計費（風險面）&quot;">​</a></h2><ul><li><strong>72 小時全球下架</strong>：美商務部 2026-06-12 出口管制 → Fable 5/Mythos 5 上線 3 天即停；覆蓋全球非美籍用戶（含 Anthropic 自家員工）<strong>及 AWS Bedrock 客戶</strong>。Nathan Lambert：「AI 治理新紀元起跑槍」。</li><li><strong>WH「不可越獄」vs 資安專家「技術上不可能」</strong>：100+ 高管（Adobe/Zoom/Sophos/Vercel/Nvidia/Stanford HAI/Alex Stamos）聯署 Free Fable，三論點：① GPT-5.5/Kimi2.7 同等能力未被限 → ban 無效；② ban 傷防禦方（PoC 是防禦標準，Moussouris：1000h 紅隊未現通用越獄）；③ 應建科學/透明監管。</li><li><strong>最新（至 06-20）</strong>：尚未解禁；唯一官方時程 = 身份驗證機制 <strong>2026-07-08</strong> 部署（可能為解禁前置）。</li><li><strong>計費撤回</strong>：Agent SDK 計費分離原定 06-15 生效 → 撤回「nothing changes for now」；原因 OpenAI 降價 + IPO 估值 + 監管後患。</li><li><strong>多模型路由最佳實踐</strong>（評論綜合）：抽象層先行（API gateway + normalized schema）、MCP 開放標準、<strong>provider-level 多元化</strong>（換 cloud 無用 — Bedrock 同受影響）、自動 fallback 路由（72h 無預警 → 不能靠人工切換）。</li></ul><hr><h2 id="_5-主題-e-—-proactive-agent-成本現實-v-simon-willison-一手" tabindex="-1">5. 主題 E — Proactive Agent 成本現實（V，Simon Willison 一手） <a class="header-anchor" href="#_5-主題-e-—-proactive-agent-成本現實-v-simon-willison-一手" aria-label="Permalink to &quot;5. 主題 E — Proactive Agent 成本現實（V，Simon Willison 一手）&quot;">​</a></h2><p>單一 textarea scrollbar debug：<strong>$12.11</strong> full-price / <strong>68,606</strong> output tokens / peak context <strong>113,178</strong>（Fable 5 + Opus 4.8 混用）。Fable「relentlessly proactive」自發行為：建 Datasette dev server、3 瀏覽器 Playwright、Python CORS server 捕 JSON、注入 JS 跨域、osascript/screencapture 截圖 pipeline、Shadow DOM 遍歷。 <strong>安全（V）</strong>：「agents operating outside sandboxes can execute any terminal command a human could」——proactive 放大 prompt-injection 攻擊面（無需明確指令即自主行動 = 完整 shell）。</p><hr><h2 id="_6-對本-workspace-的影響-接地既有設計" tabindex="-1">6. 對本 workspace 的影響（接地既有設計） <a class="header-anchor" href="#_6-對本-workspace-的影響-接地既有設計" aria-label="Permalink to &quot;6. 對本 workspace 的影響（接地既有設計）&quot;">​</a></h2><blockquote><p>原則：本週證據多為 workspace 既有契約的<strong>外部實證背書</strong>（驗證既有 &gt; 新增規則，core.md Framework Integrity）。</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>發現</th><th>workspace 對應（grep 接地）</th><th>處置</th></tr></thead><tbody><tr><td>6.1</td><td>CC 98.4% 確定性「AI 需被管理非更聰明」</td><td>core.md:69「LLM 只做判斷／確定性代碼做決定」+ CLAUDE.md「硬性執行交 hooks」</td><td><strong>RECORD</strong>：官方架構與 workspace 命題同構</td></tr><tr><td>6.2</td><td>93% approval fatigue → 重構邊界非加警告</td><td>settings.json:6 <code>bypassPermissions</code> + hooks 硬性攔截</td><td><strong>RECORD</strong>：workspace 已採此結論（靠 hooks 非 prompt）</td></tr><tr><td>6.3</td><td>5 層 compaction / summary-only subagent returns</td><td>context-management.md（compact 觸發）+ subagent-strategy:17「child 輸出只含結果」+ feature.sh worktree</td><td><strong>RECORD</strong>：設計對齊</td></tr><tr><td>6.4</td><td>Harness 23.8pt spread + DeepSWE 榜</td><td>EVOLUTION-QUEUE <code>model-selection-grid-deepSWE-update</code>（pending）</td><td><strong>PROPOSE→DEFER</strong>：補一手佐證(Harness-Bench arXiv) + BenchLM(V)，仍走人工審核</td></tr><tr><td>6.5</td><td>72h 全球下架（含 Bedrock）single-provider 風險</td><td>4 pilot 全 Anthropic（grid:19）；無 fallback 層</td><td><strong>OPEN-QUESTION</strong>：架構決策，待使用者定奪（見下）</td></tr><tr><td>6.6</td><td>Proactive $12.11 / 68.6K tokens</td><td>context-management.md:18 token budget per-task 4K</td><td><strong>RECORD</strong>：成本現實印證 budget 必要</td></tr></tbody></table><h3 id="_6-5-open-question-off-rails-不自決" tabindex="-1">6.5 OPEN-QUESTION（off-rails，不自決） <a class="header-anchor" href="#_6-5-open-question-off-rails-不自決" aria-label="Permalink to &quot;6.5 OPEN-QUESTION（off-rails，不自決）&quot;">​</a></h3><p><strong>問題</strong>：Fable 5 的 72h 無預警全球下架（含 Bedrock）證明 single-provider 是<strong>監管單點失效</strong>。workspace 4 個 pilot 全 Anthropic。是否引入多供應商 fallback 路由層？ <strong>為何不自決</strong>：此為跨模組架構決策（off-rails），涉成本/複雜度/維護權衡，core.md 規定「規格未定義邊界 → open question 回報不自決」。 <strong>選項供使用者裁決</strong>：(a) 維持 Anthropic-only + 接受監管風險（最簡，符現狀）；(b) grid 加一條「非 Anthropic 緊急 fallback」純文件提示（低成本，不改執行路徑）；(c) 真正多供應商路由層（高成本，可能過度工程）。<strong>傾向 (b)</strong> — 最小可逆、記錄風險不過度建設。</p><hr><h2 id="_7-apply-defer-open-帳本" tabindex="-1">7. APPLY / DEFER / OPEN 帳本 <a class="header-anchor" href="#_7-apply-defer-open-帳本" aria-label="Permalink to &quot;7. APPLY / DEFER / OPEN 帳本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>行動</th><th>類型</th><th>處置</th><th>Gate</th></tr></thead><tbody><tr><td>6.1–6.3, 6.6</td><td>CC 架構 / approval / compaction / 成本 獲背書</td><td>RECORD</td><td>記錄對應</td><td>零變更</td></tr><tr><td>6.4</td><td>grid DeepSWE 更新補一手佐證</td><td>PROPOSE</td><td><strong>DEFER → EVOLUTION-QUEUE 人工審核</strong></td><td><code>.claude/</code> 變更，已 pending</td></tr><tr><td>6.5</td><td>多供應商 fallback 路由</td><td>OPEN-QUESTION</td><td><strong>待使用者裁決</strong>（傾向選項 b）</td><td>off-rails 架構決策</td></tr></tbody></table><blockquote><p><strong>本報告零 .claude/ inline 變更</strong>。6.4 須走既有 EVOLUTION-QUEUE 審核；6.5 須使用者拍板後才入 EVOLUTION-QUEUE。</p></blockquote><hr><h2 id="_8-來源" tabindex="-1">8. 來源 <a class="header-anchor" href="#_8-來源" aria-label="Permalink to &quot;8. 來源&quot;">​</a></h2><p><strong>一手 / 學術</strong>：</p><ul><li><a href="https://arxiv.org/html/2604.14228v1" target="_blank" rel="noreferrer">Dive into Claude Code — VILA-Lab arXiv 2604.14228</a> · <a href="https://github.com/VILA-Lab/Dive-into-Claude-Code" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://arxiv.org/html/2605.27922v1" target="_blank" rel="noreferrer">Harness-Bench arXiv 2605.27922</a></li><li><a href="https://claude.com/blog/building-with-claude-managed-agents" target="_blank" rel="noreferrer">Building with Claude Managed Agents — Anthropic</a></li><li><a href="https://simonwillison.net/2026/Jun/11/fable-is-relentlessly-proactive/" target="_blank" rel="noreferrer">Claude Fable is relentlessly proactive — Simon Willison</a></li></ul><p><strong>Benchmark / 治理</strong>：</p><ul><li><a href="https://benchlm.ai/benchmarks/deepSwe" target="_blank" rel="noreferrer">BenchLM DeepSWE Leaderboard</a> · <a href="https://mer.vin/2026/05/deepswe-benchmark-how-datacurve-separates-real-agentic-coding-ability/" target="_blank" rel="noreferrer">DeepSWE methodology — mer.vin</a></li><li><a href="https://www.interconnects.ai/p/welcome-to-the-agi-era-of-ai-governance" target="_blank" rel="noreferrer">Welcome to the AGI Era of Governance — Nathan Lambert</a></li><li><a href="https://www.therundown.ai/p/why-100-security-experts-say-the-fable-5-ban-backfires" target="_blank" rel="noreferrer">Free Fable 公開信 — The Rundown</a> · <a href="https://cyberscoop.com/cybersecurity-experts-anthropic-fable-5-not-unique-ai-threat/" target="_blank" rel="noreferrer">CyberScoop</a></li><li><a href="https://the-decoder.com/anthropic-backs-off-unpopular-billing-overhaul-as-price-war-with-openai-looms/" target="_blank" rel="noreferrer">計費撤回 — The Decoder</a> · <a href="https://isfableback.org/" target="_blank" rel="noreferrer">IsFableBack.org</a></li></ul><hr><p><em>方法：3× researcher 平行 fan-out → 主對話交叉核驗綜合 → fable-pilot 審閱。量化標 V/D；.claude/ 變更走 EVOLUTION-QUEUE；架構決策為 open question 待使用者裁決。</em></p>',52)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
